  if(seen.has(row.id)||!p.originalCatalogue.shoes.some(x=>x.id===row.id))throw Error('Shoe Batch 3 identity differs: '+row.id);
  if(row.baseline_layer===null){if(row.id!=='shoe-27'||p.shoeLayers[row.id])throw Error('Unexpected new shoe connection: '+row.id);}
  else if(p.shoeLayers[row.id]?.sha256!==row.baseline_layer)throw Error('Shoe Batch 3 baseline differs: '+row.id);
