function shoeFamily(x){if(shoeColours[x.color])return shoeColours[x.color];let d=(x.color||'').toLowerCase();return /black/.test(d)?'black':/brown|cognac|chestnut|tan|oxblood|chocolate|nubuck/.test(d)?'brown':/navy/.test(d)?'navy':/white|cream|beige/.test(d)?'light':/grey|gray/.test(d)?'grey':'other';}
