   if(item.image){const img=document.createElement('img');img.className='lb-swatch';img.src=root.HEWRS_EMBEDDED_UI_IMAGES?.[item.image.sha256]||item.image.src;img.width=192;img.height=224;img.alt=(item.id||'')+' — '+item.name+(item.image.source_kind==='owner_reference_photo'?'; owner-supplied reference photograph':'; registered source detail');img.decoding='async';img.dataset.sourceKey=item.image.source_key;img.onerror=()=>{img.hidden=true;row.classList.add('lb-image-unavailable');const msg=document.createElement('small');msg.textContent='Thumbnail unavailable; item identity retained.';row.append(msg);};if(onItem){const b=document.createElement('button');b.type='button';b.className='lb-swatch-button';b.setAttribute('aria-label','Enlarge '+item.role.toLowerCase()+' '+(item.id||'')+' — '+item.name);b.append(img);b.onclick=()=>onItem(clone(item));row.append(b);}else row.append(img);}
